                guard let v = ContactPhotoSize(wire: w1) else { return settle.reject("bad arguments — Contacts.photo: size") }
                a1 = v
            }
            let reply = Reply<PluginFile?, ContactsCode>(settle) { v, w in if let v1 = v { v1.write(to: w) } }
            permissions.ensure([.contacts]) { [plugin] granted in
                guard granted else { return reply.reject(.denied) }
                plugin.photo(a0, a1, reply)
            }
        case "add":
            guard let a0 = ContactDraft(wire: args[0]) else { return settle.reject("bad arguments — Contacts.add: draft") }
            plugin.add(a0, Reply<Bool, ContactsCode>(settle) { v, w in w.bool(v) })
        case "show":
            guard let a0 = args[0].string else { return settle.reject("bad arguments — Contacts.show: id") }
            let reply = Reply<Void, ContactsCode>(settle)
            permissions.ensure([.contacts]) { [plugin] granted in
                guard granted else { return reply.reject(.denied) }
                plugin.show(a0, reply)
            }
        case "$listen":
            // The wrapper's own call: the app began or stopped listening to a @lazy event.
            guard let event = args[0].string, let on = args[1].bool else { return settle.reject("bad arguments — $listen") }
            switch event {
            case "changed": if observed.set(event, on) { plugin.changedObserved(on) }
            default: return settle.reject("Unknown event: \(event)")
            }
            settle.resolve()
        default:
            settle.reject("Unknown method: \(method)")
        }
    }

    func close() { plugin.close() }
}
